INSERT INTO mall_order (
    order_no, user_id, status, total_amount, user_coupon_id, coupon_name,
    coupon_discount_amount, payment_amount, total_quantity,
    receiver_name, receiver_phone, receiver_address, remark, created_at, updated_at
) VALUES (
    #{orderNo}, #{userId}, #{status}, #{totalAmount}, #{userCouponId}, #{couponName},
    #{couponDiscountAmount}, #{paymentAmount}, #{totalQuantity},
    #{receiverName}, #{receiverPhone}, #{receiverAddress}, #{remark}, #{createdAt}, #{createdAt}
)

mapper.select:
SELECT id, order_no, user_id, status, total_amount, user_coupon_id, coupon_name,
       coupon_discount_amount, payment_amount, total_quantity,
       receiver_name, receiver_phone, receiver_address, remark, created_at, updated_at
FROM mall_order
WHERE id = #{id}
  AND user_id = #{userId}
